CREATE TABLE tt_stock_items(id INTEGER PRIMARY KEY,product_id INT,qty_on_hand DECIMAL(12,2),qty_reserved DECIMAL(12,2),location_code TEXT);
CREATE TABLE tt_stock_ledger(id INTEGER PRIMARY KEY,trans_code TEXT,trans_type TEXT,product_id INT,qty_change DECIMAL(12,2),balance_after DECIMAL(12,2),location_code TEXT,created_by INT,note TEXT);
