INSERT INTO tt_users VALUES(1,'a@example.invalid','Admin','ADMIN',1),(2,NULL,'Worker','SALES',1),(3,NULL,'Inspector','SALES',1),(4,NULL,'Sales','SALES',1),(5,NULL,'Engineer','SALES',1);
INSERT INTO tt_tool_instances VALUES(1,'NN-D12-011','Tool 1','D12','NEW','WAREHOUSE',NULL,0),(2,'NN-D12-010','Tool 2','D12','NEW','WAREHOUSE',NULL,0);");
production_migrate($db); production_migrate($db);
$db->exec("UPDATE tt_users SET workshop_role='CNC' WHERE id=2; UPDATE tt_users SET workshop_role='INSPECTOR' WHERE id=3; UPDATE tt_users SET workshop_role='ENGINEER' WHERE id=5; UPDATE tt_tool_instances SET self_checkout_enabled=1 WHERE id=1");
$admin=new ProductionService($db,array('id'=>1,'name'=>'Admin','role'=>'ADMIN','session_version'=>1));
$worker=new ProductionService($db,array('id'=>2,'name'=>'Worker','role'=>'SALES','workshop_role'=>'CNC','session_version'=>1));
