$sales=new ProductionService($db,array('id'=>4,'name'=>'Sales','role'=>'SALES','session_version'=>1));
$count=0;
function check($condition,$message) { global $count; if (!$condition) throw new Exception($message); $count++; }
function fails($status,$fn) { try { $fn(); } catch (ProductionError $e) { check($e->status===$status,'Unexpected status: '.$e->status.' '.$e->getMessage()); return; } throw new Exception('Expected failure '.$status); }
$seq=0;
function writeRequest($s,$a,$p) { global $seq; return $s->write($a,$p,str_pad((string)++$seq,20,'0',STR_PAD_LEFT)); }
check(ProductionService::meters('1.99')===199,'fixed point 1.99');
check(ProductionService::meters('2.01')===201,'fixed point 2.01');
fails(422,function(){ProductionService::meters('-1');});
fails(422,function(){ProductionService::meters('1.999');});
fails(403,function()use($sales){$sales->resolve('NN-D12-011');});
fails(404,function()use($worker){$worker->resolve('nn-d12-011');});
fails(422,function()use($worker){writeRequest($worker,'production_self_checkout',array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW'));});
$scan=writeRequest($worker,'production_scan_create',array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW'));
$payload=array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW','scan_token'=>$scan['scan_token']);
$result=$worker->write('production_self_checkout',$payload,'same-request-000001');
check($worker->write('production_self_checkout',$payload,'same-request-000001')===$result,'lost response replay');
fails(409,function()use($worker,$payload){$payload['drawing_code']='OTHER';$worker->write('production_self_checkout',$payload,'same-request-000001');});
fails(409,function()use($admin){writeRequest($admin,'production_tool_checkout',array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW','holder_user_id'=>2,'manual_reason'=>'Test'));});
