writeRequest($worker,'production_return_request',array('movement_id'=>$id));
check($db->query('SELECT returned_at FROM tt_tool_movements WHERE id='.$id)->fetchColumn()===null,'request is not receipt');
fails(403,function()use($worker,$id){writeRequest($worker,'production_tool_checkin',array('movement_id'=>$id));});
writeRequest($admin,'production_tool_checkin',array('movement_id'=>$id));
check($db->query('SELECT current_location FROM tt_tool_instances WHERE id=1')->fetchColumn()==='INSPECTION','received must inspect');
fails(409,function()use($admin,$id){writeRequest($admin,'production_tool_checkin',array('movement_id'=>$id));});
fails(409,function()use($admin){writeRequest($admin,'production_tool_checkout',array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW','holder_user_id'=>2,'manual_reason'=>'Test'));});
fails(403,function()use($worker,$id){writeRequest($worker,'production_tool_inspect',array('movement_id'=>$id,'returned_status'=>'OLD'));});
writeRequest($inspector,'production_tool_inspect',array('movement_id'=>$id,'returned_status'=>'USED_1X','flank_wear_vb_mm'=>'0.1'));
check($db->query('SELECT current_location FROM tt_tool_instances WHERE id=1')->fetchColumn()==='WAREHOUSE','inspection release');
fails(409,function()use($inspector,$id){writeRequest($inspector,'production_tool_inspect',array('movement_id'=>$id,'returned_status'=>'OLD'));});
$before=$db->query('SELECT COUNT(*) FROM tt_tool_movements')->fetchColumn();
writeRequest($admin,'production_night_reconcile',array('movement_id'=>$id));
check($before==$db->query('SELECT COUNT(*) FROM tt_tool_movements')->fetchColumn(),'reconcile no issue');
$p=array('tool_code'=>'NN-D12-011','drawing_code'=>'DRAW','holder_user_id'=>2,'manual_reason'=>'Manual exception');
$next=writeRequest($admin,'production_tool_checkout',$p);
fails(404,function()use($admin,$next){writeRequest($admin,'production_tool_batch_checkin',array('items'=>array(array('movement_id'=>$next['movement_id']),array('movement_id'=>9999))));});
check($db->query('SELECT current_location FROM tt_tool_instances WHERE id=1')->fetchColumn()==='CNC_SHOP','batch failure rollback');
fails(422,function()use($admin,$next){writeRequest($admin,'production_tool_issue_reverse',array('movement_id'=>$next['movement_id'],'reason'=>'Fixture correction'));});
writeRequest($admin,'production_tool_issue_reverse',array('movement_id'=>$next['movement_id'],'reason'=>'Fixture correction','physical_return_confirmed'=>true));
check((int)$db->query('SELECT COUNT(*) FROM tt_production_corrections')->fetchColumn()===1,'original preserved in correction');
check($db->query('SELECT current_location FROM tt_tool_instances WHERE id=1')->fetchColumn()==='WAREHOUSE','correction returns custody');
fails(403,function()use($worker,$next){writeRequest($worker,'production_tool_issue_reverse',array('movement_id'=>$next['movement_id'],'reason'=>'Not permitted','physical_return_confirmed'=>true));});
fails(409,function()use($admin,$next){writeRequest($admin,'production_tool_issue_reverse',array('movement_id'=>$next['movement_id'],'reason'=>'Again','physical_return_confirmed'=>true));});
$expired=writeRequest($worker,'production_scan_create',array('tool_code'=>'NN-D12-011','drawing_code'=>'EXPIRED'));
$db->exec('UPDATE tt_production_scans SET expires_at=0');
fails(409,function()use($worker,$expired){writeRequest($worker,'production_self_checkout',array('tool_code'=>'NN-D12-011','drawing_code'=>'EXPIRED','scan_token'=>$expired['scan_token']));});
$db->exec('UPDATE tt_users SET session_version=2 WHERE id=2');
fails(401,function()use($worker){writeRequest($worker,'production_scan_create',array('tool_code'=>'NN-D12-010','drawing_code'=>'DRAW'));});
foreach (array('0','1.99','2','2.01') as $returned) {
    $issue=writeRequest($admin,'production_wip_advance',array('stock_item_id'=>1,'project_code'=>'PROJECT','engineer_user_id'=>2,'advance_length_meters'=>'5'));
    $ret=writeRequest($admin,'production_wip_return',array('wip_id'=>$issue['wip_id'],'returned_length_meters'=>$returned,'measurement_method'=>'MANUAL_TAPE'));
    check(ProductionService::meters($ret['consumed_length_meters'])+ProductionService::meters($ret['returned_length_meters'])+ProductionService::meters($ret['scrap_length_meters'])===500,'conserve meters '.$returned);
    check(ProductionService::meters($ret['returned_length_meters'])===(ProductionService::meters($returned)>=200?ProductionService::meters($returned):0),'remnant threshold '.$returned);
    fails(409,function()use($admin,$issue){writeRequest($admin,'production_wip_return',array('wip_id'=>$issue['wip_id'],'returned_length_meters'=>'1','measurement_method'=>'MANUAL_TAPE'));});
}
$stockBefore=$db->query('SELECT qty_on_hand FROM tt_stock_items WHERE id=1')->fetchColumn();
fails(409,function()use($admin){writeRequest($admin,'production_wip_advance',array('stock_item_id'=>1,'project_code'=>'PROJECT','engineer_user_id'=>2,'advance_length_meters'=>'999'));});
check($stockBefore==$db->query('SELECT qty_on_hand FROM tt_stock_items WHERE id=1')->fetchColumn(),'overissue rollback');
$engineer=new ProductionService($db,array('id'=>5,'name'=>'Engineer','role'=>'SALES','workshop_role'=>'ENGINEER','session_version'=>1));
$issue=writeRequest($admin,'production_wip_advance',array('stock_item_id'=>1,'project_code'=>'REQUEST','engineer_user_id'=>5,'advance_length_meters'=>'5'));
$before=$db->query('SELECT qty_on_hand FROM tt_stock_items WHERE id=1')->fetchColumn();
writeRequest($engineer,'production_wip_return_request',array('wip_id'=>$issue['wip_id'],'returned_length_meters'=>'2'));
check($before==$db->query('SELECT qty_on_hand FROM tt_stock_items WHERE id=1')->fetchColumn(),'engineer request is not receipt');
fails(403,function()use($engineer,$issue){writeRequest($engineer,'production_wip_return',array('wip_id'=>$issue['wip_id'],'returned_length_meters'=>'2','measurement_method'=>'MANUAL_TAPE'));});
check($db->query('SELECT COUNT(*) FROM tt_production_audit')->fetchColumn()>=5,'audit recorded');
echo 'PASS '.$count." domain assertions (SQLite smoke; MariaDB concurrency is a separate gate)\n";
